window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a9a1cad3b740aee3"]={"versions": [{"id": "FIG-a9a1cad3b740aee3", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Software-Component-Template. Dargestellt ist die strukturelle Definition und Einbindung von <code>EcuAbstractionComponentType</code> innerhalb der AUTOSAR-Architektur als spezialisierter Softwarekomponententyp mit Verknüpfung zu Hardwareressourcen und Basissoftware-Modulbeschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Components::EcuAbstractionComponentType</code>: Spezialisierung von <code>AtomicSoftwareComponentType</code>. Besitzt zwei gerichtete Assoziationen:\n<ul class=\"fig-list\"><li><code>+hardwareElement</code>: Rolle zur Referenzierung von Ziel-Entitäten des Typs <code>ECUResourceTemplate::HWElement</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>+bswModuleDescription</code>: Rolle zur Referenzierung von Entitäten des Typs <code>BswOverview::BswModuleDescription</code> mit der Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>ECUResourceTemplate::HWElement</code>: Stereotypisiert bzw. abgeleitet als <code>ARElement</code>. Enthält das Attribut <code>+ standbyCurrent: Float [0..1]</code>.\n</li><li><code>BswOverview::BswModuleDescription</code>: Stereotypisiert bzw. abgeleitet als <code>ARElement</code> mit Stereotyp <code>«atpStructureElement»</code>. Enthält das Attribut <code>+ moduleId: Int</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es werden keine Laufzeitabläufe, Protokolle oder dynamischen Sequenzen modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>EcuAbstractionComponentType</code> dient der Kapselung und Abstraktion von Steuergeräte-Hardwarefunktionen gegenüber darüberliegenden Softwareschichten. Ein <code>EcuAbstractionComponentType</code> darf über die Kardinalität <code>0..*</code> mehrere oder keine Hardwareelemente (<code>HWElement</code>) sowie zugeordnete Basissoftware-Modulbeschreibungen (<code>BswModuleDescription</code>) referenzieren. Beide Zieltypen stellen eigenständige <code>ARElement</code>-Definitionen dar. Das Attribut <code>moduleId</code> ist als primitiver Typ <code>Int</code> typisiert.</p>"}, {"id": "FIG-eaa4fb92d9cc99fb", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Software-Component-Template. Dargestellt ist die strukturelle Definition und Einbindung von <code>EcuAbstractionComponentType</code> innerhalb der AUTOSAR-Architektur als spezialisierter Softwarekomponententyp mit Verknüpfung zu Hardwareressourcen und Basissoftware-Modulbeschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Components::EcuAbstractionComponentType</code>: Spezialisierung von <code>AtomicSoftwareComponentType</code>. Besitzt zwei gerichtete Assoziationen:\n<ul class=\"fig-list\"><li><code>+hardwareElement</code>: Rolle zur Referenzierung von Ziel-Entitäten des Typs <code>ECUResourceTemplate::HWElement</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>+bswModuleDescription</code>: Rolle zur Referenzierung von Entitäten des Typs <code>BswOverview::BswModuleDescription</code> mit der Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>ECUResourceTemplate::HWElement</code>: Stereotypisiert bzw. abgeleitet als <code>ARElement</code>. Enthält das Attribut <code>+ standbyCurrent: Float [0..1]</code>.\n</li><li><code>BswOverview::BswModuleDescription</code>: Stereotypisiert bzw. abgeleitet als <code>ARElement</code> mit Stereotyp <code>«atpStructureElement»</code>. Enthält das Attribut <code>+ moduleId: Int</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es werden keine Laufzeitabläufe, Protokolle oder dynamischen Sequenzen modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>EcuAbstractionComponentType</code> dient der Kapselung und Abstraktion von Steuergeräte-Hardwarefunktionen gegenüber darüberliegenden Softwareschichten. Ein <code>EcuAbstractionComponentType</code> darf über die Kardinalität <code>0..*</code> mehrere oder keine Hardwareelemente (<code>HWElement</code>) sowie zugeordnete Basissoftware-Modulbeschreibungen (<code>BswModuleDescription</code>) referenzieren. Beide Zieltypen stellen eigenständige <code>ARElement</code>-Definitionen dar. Das Attribut <code>moduleId</code> ist als primitiver Typ <code>Int</code> typisiert.</p>"}, {"id": "FIG-19ecbc92f2fc8365", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Software-Component-Template. Dargestellt ist die strukturelle Definition und Einbindung von <code>EcuAbstractionComponentType</code> innerhalb der AUTOSAR-Architektur als spezialisierter Softwarekomponententyp mit Verknüpfung zu Hardwareressourcen und Basissoftware-Modulbeschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Components::EcuAbstractionComponentType</code>: Spezialisierung von <code>AtomicSoftwareComponentType</code>. Besitzt zwei gerichtete Assoziationen:\n<ul class=\"fig-list\"><li><code>+hardwareElement</code>: Rolle zur Referenzierung von Ziel-Entitäten des Typs <code>ECUResourceTemplate::HWElement</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>+bswModuleDescription</code>: Rolle zur Referenzierung von Entitäten des Typs <code>BswOverview::BswModuleDescription</code> mit der Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>ECUResourceTemplate::HWElement</code>: Stereotypisiert bzw. abgeleitet als <code>ARElement</code>. Enthält das Attribut <code>+ standbyCurrent :Float [0..1]</code>.\n</li><li><code>BswOverview::BswModuleDescription</code>: Stereotypisiert bzw. abgeleitet als <code>ARElement</code> mit Stereotyp <code>«atpStructureElement»</code>. Enthält das Attribut <code>+ moduleId :Integer</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es werden keine Laufzeitabläufe, Protokolle oder dynamischen Sequenzen modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>EcuAbstractionComponentType</code> dient der Kapselung und Abstraktion von Steuergeräte-Hardwarefunktionen gegenüber darüberliegenden Softwareschichten. Ein <code>EcuAbstractionComponentType</code> darf über die Kardinalität <code>0..*</code> mehrere oder keine Hardwareelemente (<code>HWElement</code>) sowie zugeordnete Basissoftware-Modulbeschreibungen (<code>BswModuleDescription</code>) referenzieren. Beide Zieltypen stellen eigenständige <code>ARElement</code>-Definitionen dar. Das Attribut <code>moduleId</code> ist als primitiver Metamodelltyp <code>Integer</code> spezifiziert.</p>"}], "trans": [{"from": "FIG-a9a1cad3b740aee3", "to": "FIG-eaa4fb92d9cc99fb", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-eaa4fb92d9cc99fb", "to": "FIG-19ecbc92f2fc8365", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>BswModuleDescription</code>: Datentyp des Attributs <code>moduleId</code> von <code>Int</code> zu <code>Integer</code> geändert.\n</li><li><code>HWElement</code>: Typangabe des Attributs <code>standbyCurrent</code> formatiert zu <code>:Float [0..1]</code>.\n</li></ul>"}]};
